# פרק 10 (שלד אוטומטי מהתוכן הקיים; להעמקה)
N=10
TITLE='הסגת גבול ומטרד'
SUM=[' <p>עוולות פרטיקולריות המגִנות על הקניין ועל השימוש וההנאה מהמקרקעין.</p> <h3>10.1 הסגת גבול במקרקעין — סעיפים 29–30</h3> <p><strong>סעיף 29</strong>: "כניסה למקרקעין שלא כדין, או היזק או הפרעה... שלא כדין" — אך אין פיצוי אלא אם נגרם <strong>נזק ממון</strong>. <strong>סעיף 30</strong>: נטל ההוכחה ש"כדין" מוטל על <strong>הנתבע</strong>.</p> <h3>10.2 הסגת גבול במיטלטלין — סעיף 31</h3> <p>לקיחת טובין שלא כדין מהחזקת אדם, או הפרעה אלימה בהם — בכפוף לקיומו של נזק ממון.</p> <h3>10.3 מטרד — סעיפים 42–44</h3> <p><strong>מטרד ליחיד</strong> (<strong>סעיף 44</strong>): הפרעה של ממש ובלתי סבירה לשימוש סביר במקרקעין או להנאה מהם (רעש, ריח, עשן) — לפי סבירות ההפרעה ביחס לאופי המקום ומשכה. <strong>מטרד לרבים</strong> (<strong>סעיפים 42–43</strong>): פגיעה בנוחות הציבור; תביעה פרטית מותנית ב<strong>נזק מיוחד</strong> מעבר לציבור.</p> <h3>10.4 נקודות מפתח למבחן</h3> <ul><li>הסגת גבול מקרקעין (ס׳ 29) — דרוש נזק ממון; הנטל על הנתבע (ס׳ 30).</li><li>מטרד ליחיד (ס׳ 44) — הפרעה של ממש ובלתי סבירה.</li><li>מטרד לרבים (42–43) — נדרש נזק מיוחד לתביעה פרטית.</li></ul> <p style="margin-top:18px;padding-top:9px;border-top:1px solid var(--line,#3a342a);font-size:11px;color:var(--muted,#8a8475)">© כל הזכויות שמורות ל<b>אילן פרץ</b> · אין להעתיק, לשכפל או להפיץ ללא רשות בכתב.</p>']
CASES=[("ס' 29 לפקודת הנזיקין — הסגת גבול במקרקעין", '', 'כניסה/היזק/הפרעה למקרקעין שלא כדין; פיצוי מותנה בנזק ממון, ונטל ה"כדין" על הנתבע.'), ("ס' 44 — מטרד ליחיד", '', 'הפרעה של ממש ובלתי סבירה לשימוש סביר במקרקעין או להנאה מהם (רעש, ריח, עשן).'), ("ס' 42-43 — מטרד לרבים", '', 'פגיעה בנוחות הציבור; תביעה פרטית מותנית בנזק מיוחד מעבר לכלל הציבור.'), ('ע״א 44/76 אתא חברה לטכסטיל בע״מ נ׳ שוורץ', 'שכן של מפעל הטקסטיל בקרית אתא תבע בשל רעש עז ממכונות הקירור. הערכאות הקודמות קבעו שמדובר במטרד ליחיד ונתנו צו מניעה, והמפעל ערער בטענה שיש לפסוק פיצויים במקום צו בשל הנזק הכלכלי לעובדים ולמשק.', 'השופט שמגר דחה את הערעור: החריג בס׳ 74 דורש ארבעה תנאים מצטברים — פגיעה קטנה, ניתנת להערכה בכסף, ניתנת לפיצוי מספיק, וצו שהוא התעמרות. כשהפגיעה חמורה הניזוק זכאי לצו. שיקולים כלכליים השוואתיים אינם מכריעים, והתועלת שבפעילות הנתבע אינה מבטלת את זכות הפרט להנאה סבירה מנכסו.'), ('ע״א 436/60 עזרי נ׳ קליין', 'תביעת מטרד בשל רעש שהפריע לדיירים באזור מעורב, שבו בתי מגורים סמוכים לבתי מלאכה ולמסחר.', 'נקבע שסבירות ההפרעה נבחנת לפי השימושים בפועל באזור: תושב אזור שכולו מגורים זכאי לשקט רב יותר מתושב אזור מעורב — אבל גם האחרון זכאי למידה מינימלית של הנאה מדירתו. טיב המקרקעין משמעותי בקביעת סבירות השימוש.'), ('ע״א 17/62 לטוביצקי נ׳ לפלר', 'דיון בשאלה אם חסימת נוף ומראה מנכס סמוך יכולה להוות מטרד ליחיד.', 'ביהמ״ש לא הכיר בפגיעה בנוף ובמראה כהפרעה המקימה עילת מטרד ליחיד. ההלכה מבחינה בין הפרעות פיזיות וחושיות (רעש, ריח, רעידות) לבין אינטרסים אסתטיים שאינם מוגנים בעוולה זו.'), ('ע״א 407/54 בית משותף ג׳ פתח-תקוה בע״מ נ׳ למפרט', 'דיון בפגיעה ביציבות בניין שנגרמה מעבודות במקרקעין שכנים, בתקופה שלפני חקיקת חוק המקרקעין.', 'שלילת תמיכה ממקרקעין שכנים הוכרה כמטרד ליחיד, משום שהיא פוגעת בהנאת הבעלים מנכסם. לאחר מכן הוסף לפקודה ס׳ 48א, שהפך את מניעת התמיכה לעוולה עצמאית.'), ('ע״א 891/95 זידאני נ׳ אבו-אחמד', 'תביעה של בעלי מקרקעין נגד מי שתפס אותם שלא כדין, שבה נדרשו פיצויים בגין השימוש בקרקע.', 'מסיג הגבול חוסך את דמי השימוש שהיה צריך לשלם, והבעלים מאבד את האפשרות להשכיר את הקרקע לאחר — זהו נזק ממון בר-כימות. נקבע כי בתביעת דמי שימוש ראויים מיטשטש הגבול בין פיצוי נזיקי לבין השבה מכוח עשיית עושר.'), ('ע״א 255/59 תעשיית שעם "דוד" אחים מוברמן ושות׳ בע״מ נ׳ אלרועי', 'דיון בזכות העמידה של אדם פרטי בתביעה על מטרד לציבור לפי ס׳ 43.', 'השופטים הסכימו שה"נזק ממון" הנדרש לפי ס׳ 43(2) הוא הפסד מוחשי הניתן לשומה בכסף, אך נחלקו בשאלה אם נדרש גם נזק מיוחד השונה מזה שנגרם לכלל הציבור. הפרשה מדגימה את הקושי של אדם פרטי לתבוע על מטרד לציבור.')]
QS=[{'q': 'מה ההבדל העקרוני בין הסגת גבול במקרקעין לבין מטרד ליחיד?', 'o': ['אין הבדל — שתיהן אותה עוולה בשמות שונים', 'מטרד חל רק על עסקים, הסגת גבול רק על פרטיים', 'הסגת גבול דורשת כוונה לפגוע, מטרד לא', 'הסגת גבול היא חדירה פיזית וישירה; מטרד הוא הפרעה עקיפה לשימוש או להנאה הנבחנת לפי סבירות'], 'c': 3, 'e': 'נכון. הסגת גבול מגינה על השליטה הפיזית בקרקע מפני חדירה; מטרד מגן על ההנאה הסבירה מפני הפרעות כמו רעש וריח, ונבחן לפי מקום, טיב ועוצמה.'}, {'q': 'שכן חנה פעם אחת ברכבו בחצר הפרטית של דנה, בלי רשות ובלי לגרום שום נזק. דנה מבקשת צו מניעה. מה הדין?', 'o': ['דנה זכאית לצו מניעה; דרישת נזק הממון מגבילה רק את הפיצויים', 'התביעה תידחה כי לא נגרם נזק ממון', 'דנה זכאית לפיצויים על עוגמת נפש', 'זו אינה הסגת גבול כי הרכב, לא השכן, נכנס לחצר'], 'c': 0, 'e': 'נכון. ס׳ 71 מסמיך את ביהמ״ש ליתן ציווי גם כשלא נתבעו או לא נפסקו פיצויים; כניסה שלא כדין מספיקה לצו.'}, {'q': 'בתביעה על הסגת גבול במקרקעין, על מי מוטל הנטל להוכיח שהכניסה הייתה כדין?', 'o': ['על המדינה', 'על התובע', 'על שני הצדדים בחלקים שווים', 'על הנתבע, לפי ס׳ 30'], 'c': 3, 'e': 'נכון. ס׳ 30 מעביר לנתבע את הנטל להוכיח שהמעשה לא היה שלא כדין — למשל שהייתה לו רשות או זכות.'}, {'q': 'קבלן הקים קיר שחרג חצי מטר לחלקת השכן, כי סבר בתום לב שהגבול עובר שם לפי מפה ישנה. האם עומדת לו הגנה?', 'o': ['כן — טעות בתום לב היא הגנה מלאה', 'לא — לפי ס׳ 33 טעות בנוגע לבעלות, אפילו בתום לב, אינה הצדק להפרעה בנכסי אחר', 'כן — אם יוכיח שהתכוון לטובת השכן', 'כן — כי מדובר בהפרעה קטנה'], 'c': 1, 'e': 'נכון. העוולה מגינה על הזכות ולא בודקת אשמה; הקבלן הסיג גבול, והשכן זכאי לסעד — כולל לפי ס׳ 21 לחוק המקרקעין לגבי המחוברים.'}, {'q': 'יוסי גילה שאלמוני פלש למגרש הריק שלו והציב בו קרוואן. עברו 45 יום מיום התפיסה. יוסי שוקל להוציא אותו בעצמו בכוח סביר. מה הדין?', 'o': ['מותר רק בליווי שוטר', 'מותר אם יפצה את הפולש', 'מותר — בעלים רשאי תמיד להשתמש בכוח סביר', 'אסור — חלון 30 הימים לפי ס׳ 18(ב) לחוק המקרקעין חלף; עליו לפנות לבית המשפט'], 'c': 3, 'e': 'נכון. לאחר 30 יום יש לפנות לבית המשפט (למשל בתביעת סילוק יד לפי ס׳ 16). הוצאה בניגוד לס׳ 18(ב) עלולה לחייב את יוסי להחזיר את ההחזקה (ס׳ 19).'}, {'q': 'נער נכנס בלילה לאתר בנייה מגודר כדי לגנוב ציוד, נפל לבור לא מסומן ונפצע. מה הדין בתביעת רשלנות נגד בעל האתר בשל מצב המקרקעין?', 'o': ['ס׳ 37 שולל את אחריות התופש כלפי מסיג גבול שלא נכנס בתום לב, ולכן התביעה צפויה להיכשל', 'בעל האתר אחראי באחריות מוחלטת', 'בעל האתר אחראי כרגיל לפי ס׳ 35–36', 'התביעה תתקבל כי מדובר בקטין'], 'c': 0, 'e': 'נכון. אחריות התופש בשל מצב המקרקעין לא חלה כלפי מסיג גבול, אלא אם הוכיח שנכנס בתום לב ובלי כוונה לעבור עבירה; כאן נכנס כדי לגנוב.'}, {'q': 'מה נדרש כדי שהפרעה תהווה מטרד ליחיד לפי ס׳ 44?', 'o': ['הפרה של היתר בנייה', 'חדירה פיזית של חפץ לקרקע', 'כל אי-נוחות שהתובע חש', 'הפרעה של ממש לשימוש סביר או להנאה סבירה במקרקעין, בהתחשב במקומם ובטיבם'], 'c': 3, 'e': 'נכון. אלה רכיבי ס׳ 44(א): הפרעה של ממש, שימוש או הנאה סבירים, והתחשבות במקום ובטיב.'}, {'q': 'נגה גרה ברחוב שבו יש בתי מגורים לצד מוסכים. מוסך סמוך הוסיף משמרת לילה ורעש מכונות בוקע עד הבוקר. המוסך טוען שבאזור מעורב אין לצפות לשקט. מה הדין?', 'o': ['נגה זכאית לפיצוי רק אם הוכיחה נזק ממון', 'גם באזור מעורב זכאית נגה למידה מינימלית של הנאה; הוספת משמרת לילה ששינתה את המצב עשויה להוות מטרד', 'רק עירייה יכולה לתבוע', 'התביעה תידחה — באזור מעורב אין זכות לשקט'], 'c': 1, 'e': 'נכון. "מקומם וטיבם" מוריד את רף הציפייה אך אינו מאפס אותו; שינוי המצב הקיים ורעש לילי מחזקים את המסקנה שיש הפרעה של ממש.'}, {'q': 'בעלי וילה תובעים את שכנם שבנה קומה נוספת וחסם להם את הנוף לים. מה סיכויי התביעה במטרד ליחיד?', 'o': ['נמוכים — הפסיקה (לטוביצקי נ׳ לפלר) לא הכירה בפגיעה בנוף כמטרד ליחיד', 'גבוהים — אם הבנייה נעשתה בהיתר', 'גבוהים — פגיעה בנוף היא מטרד קלאסי', 'תלויים רק בגובה הקומה'], 'c': 0, 'e': 'נכון. ההלכה הבחינה בין הפרעות כמו רעש וריח לבין אינטרס אסתטי בנוף, שאינו מוגן בעוולה זו. ייתכן שיש לבדוק מסלולים תכנוניים.'}, {'q': 'אילו מההגנות הבאות אינה עומדת לנתבע בתביעת מטרד ליחיד?', 'o': ['שהשימוש דרוש לטובת הציבור והנזק בתחום הנסבל (ס׳ 48ב)', 'שהמטרד היה קיים לפני שהתובע רכש את הדירה (ס׳ 46)', 'שהמעשה הוא מעשה של מה בכך (ס׳ 4)', 'שהמעשה נעשה לפי הסכם המחייב את התובע (ס׳ 45)'], 'c': 1, 'e': 'נכון. ס׳ 46 קובע שאין הגנה בכך בלבד שהמטרד היה קיים לפני שהתובע הגיע; זה לכל היותר שיקול בשאלת הסבירות.'}, {'q': 'לפי פרשת אתא, מתי לא ייתן ביהמ״ש ציווי נגד מטרד אלא יסתפק בפיצויים?', 'o': ['כשמתקיימים במצטבר ארבעת תנאי ס׳ 74: פגיעה קטנה, ניתנת להערכה ולפיצוי מספיק בכסף, וצו יהיה התעמרות בנתבע', 'כשהתועלת הכלכלית של הנתבע עולה על הנזק לתובע', 'כשהתובע הגיע אחרי הנתבע', 'כשהנתבע מעסיק עובדים רבים'], 'c': 0, 'e': 'נכון. השופט שמגר פירש את ס׳ 74 כחריג מצומצם עם ארבעה תנאים מצטברים; פגיעה חמורה מזכה בצו.'}, {'q': 'מה הייחוד של עוולת הפרעה לאור שמש לפי ס׳ 48?', 'o': ['היא מגינה על כמות סבירה של אור, רק לאחר הנאה רצופה של לפחות 15 שנה שלא לפי חוזה', 'היא חלה על כל חסימת אור, מהיום הראשון', 'היא חלק מס׳ 44', 'היא מעניקה פיצויים בלבד ולא צו'], 'c': 0, 'e': 'נכון. ס׳ 48 דורש הנאה רצופה של 15 שנה שקדמו בתכוף לחסימה, ומגן על כמות סבירה בהתחשב במקום ובטיב.'}, {'q': 'מפעל שופך פסולת מסוכנת לנחל ציבורי. דייג שמתפרנס מהנחל ואיבד הכנסות רוצה לתבוע במטרד לציבור ולקבל צו. מה נכון?', 'o': ['הדייג אינו רשאי לתבוע כלל', 'רק עירייה רשאית לתבוע', 'הדייג רשאי לתבוע פיצויים אם סבל נזק ממון, אך ציווי במטרד לציבור שמור ליועמ״ש', 'הדייג רשאי לקבל צו מניעה'], 'c': 2, 'e': 'נכון. ס׳ 43(2) מתיר לאדם שסבל נזק ממון לתבוע; אובדן הכנסות מוחשי עונה על כך. לצו — יפנה ליועמ״ש או לעילות אחרות.'}, {'q': 'איזו מהטענות הבאות נכונה לגבי פיצויים במטרד ליחיד לעומת הסגת גבול?', 'o': ['במטרד ליחיד אפשר לקבל פיצוי גם על אבדן נוחות ורווחה; בהסגת גבול רק על נזק ממון', 'בהסגת גבול מפצים על כל נזק; במטרד רק על נזק ממון', 'בשתי העוולות אין פיצויים, רק צווים', 'בשתי העוולות רק נזק ממון מפוצה'], 'c': 0, 'e': 'נכון. ס׳ 29 מגביל לנזק ממון; ס׳ 44 מסתפק ב"נזק" שהגדרתו בס׳ 2 כוללת אבדן נוחות ורווחה.'}, {'q': 'עובד מחסן הוציא לבקשת מעבידו ארגזים מחצר, בהנחה בתום לב שהמעביד הוא בעליהם. התברר שהארגזים של אחר. האם העובד הסיג גבול?', 'o': ['לא — ס׳ 33(2) פוטר פועל או עובד שטיפל בנכס בדרך הרגילה של עבודתו ובדרך שהורשה, בהנחה בתום לב שמעבידו זכאי להרשות זאת', 'כן, ללא חריג', 'כן, אבל רק אם היה רשלן', 'לא, כי ארגזים אינם מיטלטלין'], 'c': 0, 'e': 'נכון. זה החריג של ס׳ 33(2) לעובד שפועל בתום לב לפי הרשאת מעבידו. האחריות עשויה לחול על המעביד.'}, {'q': 'מה קבע ביהמ״ש בע״א 164/53 צוצרסקי נ׳ סנדלר?', 'o': ['שהעוולה אינה מצטמצמת לבעלים, וגם בעל אינטרס אחר במקרקעין מוגן', 'שמטרד לציבור אינו קיים בישראל', 'שמטרד ליחיד מגן רק על בעלי מקרקעין רשומים', 'שאין פיצוי על רעש'], 'c': 0, 'e': 'נכון. נקבע שרוחב העוולה אינו מוגבל לבעלים, ובעל אינטרס אחר — כמו מחזיק או שוכר — רשאי לתבוע.'}, {'q': 'מה ההבדל בין ס׳ 17 לחוק המקרקעין לבין ס׳ 44 לפקודה?', 'o': ['ס׳ 44 חל רק על מיטלטלין', 'ס׳ 17 מגן מפני כל הפרעה אך מעניק צו בלבד; ס׳ 44 דורש הפרעה של ממש ומאפשר גם פיצויים', 'ס׳ 17 מאפשר פיצויים בלבד', 'אין הבדל'], 'c': 1, 'e': 'נכון. ס׳ 17 נותן למחזיק זכות לדרוש הימנעות מכל הפרעה וסילוקה (סעד של צו), בעוד ס׳ 44 מוגבל להפרעה של ממש אך מקנה גם פיצויים.'}, {'q': 'מהו הנוסח של ס׳ 29 לגבי פיצויים?', 'o': ['"אין תובע יכול להיפרע פיצויים על הסגת גבול במקרקעין אלא אם סבל על ידי כך נזק ממון"', '"תובע זכאי לפיצויים בלא הוכחת נזק"', '"אין תובע יכול להיפרע פיצויים אלא אם הוכיח כוונה"', '"פיצויים יינתנו רק בתביעת היועץ המשפטי לממשלה"'], 'c': 0, 'e': 'נכון. זו לשון הסיפא של ס׳ 29: הפיצויים מותנים בנזק ממון.'}, {'q': 'איזה מהמשפטים הבאים משקף נכון את ס׳ 42 (מטרד לציבור)?', 'o': ['רק פגיעה בכבישים', 'מעשה שאינו כדין או מחדל מחובה משפטית המסכן את החיים, הבטיחות, הבריאות, הרכוש או הנוחות של הציבור, או מכשול לשימוש בזכות מזכויות הכלל', 'כל הפרעה לשכן אחד', 'רק עבירה פלילית שנעשתה במקום ציבורי'], 'c': 1, 'e': 'נכון. זו הגדרת ס׳ 42 — סיכון לאינטרס ציבורי או חסימת זכות הכלל.'}, {'q': 'בעל מקרקעין תובע פולש שגר בדירתו שנתיים בלי לשלם. הפולש טוען שהדירה הייתה ריקה ממילא ולכן לא נגרם נזק. מה הדין?', 'o': ['הטענה מתקבלת — אין נזק ממון כשהדירה ריקה', 'הבעלים זכאי לפיצוי על עוגמת נפש בלבד', 'הבעלים זכאי רק לצו, לעולם לא לכסף', 'הבעלים זכאי לדמי שימוש ראויים; הפולש חסך תשלום והבעלים איבד את האפשרות להשכיר'], 'c': 3, 'e': 'נכון. בזידאני נ׳ אבו-אחמד הוסבר שהפולש חוסך דמי שימוש והבעלים מאבד את האפשרות להשכיר; לצד זה עומדת עילה של עשיית עושר.'}, {'q': 'בעל מגרש חפר יסודות עמוקים לבניין, וקיר הבית של השכן נסדק משום שהקרקע נשמטה. איזו עילה מתאימה במיוחד?', 'o': ['לשון הרע', 'מטרד לציבור', 'הסגת גבול במיטלטלין', 'מניעת תמיכה לפי ס׳ 48א'], 'c': 3, 'e': 'נכון. ס׳ 48א קובע שעשיית דבר המונע או שולל תמיכה ממקרקעין שכנים היא עוולה; זו חובה מוגברת, גם כשהעבודה בוצעה בידי קבלן.'}, {'q': "הסגת גבול במקרקעין (ס' 29) דורשת לפיצוי:", 'o': ['כוונה', 'נזק ממון', 'אלימות', 'כתב'], 'c': 1, 'e': 'אין פיצוי בלא נזק ממון.'}, {'q': 'על מי נטל ההוכחה ש"כדין"?', 'o': ['התובע', 'הנתבע', 'ביהמ"ש', 'המשטרה'], 'c': 1, 'e': "ס' 30 — על הנתבע."}, {'q': "מטרד ליחיד (ס' 44) הוא:", 'o': ['כל הפרעה', 'הפרעה של ממש ובלתי סבירה', 'כניסה', 'גזל'], 'c': 1, 'e': 'מבחן הסבירות.'}, {'q': 'לתביעת מטרד לרבים בידי פרט נדרש:', 'o': ['נזק כלשהו', 'נזק מיוחד מעבר לציבור', 'כוונה', 'חוזה'], 'c': 1, 'e': "ס' 42-43."}, {'q': 'דוגמה למטרד ליחיד:', 'o': ['גניבה', 'רעש/ריח בלתי סבירים', 'כליאה', 'לשון הרע'], 'c': 1, 'e': 'הפרעה להנאה מהמקרקעין.'}]
